    for record in self.executed:
      if record.test_name == test_name:
        return True
    return False

  def _count_eventually_passing_retries(self):
    count = 0
    for record in self.passed:
      r = record
      while r.parent is not None and r.parent[1] == TestParentType.RETRY:
        count += 1
        r = r.parent[0]
    return count

  @property
